function windowPane(x,z,axis){if(axis==='x'){box(x,1,z,.06,1.3,2,'#292a23');box(x+.04,1.1,z,.02,1.1,1.8,'#637b83');box(x+.06,1.1,z,.03,1.1,.05,'#c6c0ae');box(x+.06,1.63,z,.03,.05,1.8,'#c6c0ae');for(let o of [-1,1])box(x+.15,.8,z+o*1.05,.15,1.7,.38,'#6a6550')}else{box(x,1,z,2,1.3,.06,'#292a23');box(x,1.1,z-.04,1.8,1.1,.02,'#637b83');box(x,1.1,z-.06,.05,1.1,.02,'#c6c0ae');box(x,1.63,z-.06,1.8,.05,.02,'#c6c0ae')}}
