for(let z=.25;z<12;z+=.5)box(0,.001,z,2.9,.006,.015,'#3b3022');for(let x=-7.5;x<7.5;x+=.6){box(x,.001,6,.014,.004,8,'#3c3528')}for(let z=12;z<18;z+=.5)box(0,.001,z,7,.006,.015,'#302b20');
box(0,2.8,6,3,.05,12,'#9b9682');box(-4.5,2.8,6,6,.05,8,'#aaa58f');box(4.5,2.8,6,6,.05,8,'#aaa58f');box(0,2.8,15,7,.05,6,'#99937e');
wall(-1.05,0,.9,.18);wall(1.05,0,.9,.18);box(0,2.35,0,1.2,.45,.18,'#777563');for(let side of [-1,1]){wall(side*1.5,2.65,.18,5.3);wall(side*1.5,9.35,.18,5.3);box(side*1.5,2.35,6,.18,.45,1.4,'#a89f88');wall(side*7.5,6,.18,8);wall(side*4.5,2,6,.18);wall(side*4.5,10,6,.18);box(side*1.5,0,5.27,.24,2.4,.18,'#c3b69a');box(side*1.5,0,6.73,.24,2.4,.18,'#c3b69a')}
