box(-6.8,0,6,1.1,.86,5.7,'#777b62',true);box(-6.8,.86,6,1.25,.07,5.8,'#aaa28c');for(let z=3.5;z<9;z+=.7){box(-6.22,.12,z,.025,.61,.6,'#555e49');box(-6.19,.63,z,.04,.035,.22,'#b8ad8b');box(-7.22,1.5,z,.45,.8,.65,'#84876c')}for(let z=3.3;z<8.8;z+=.3)for(let y=.96;y<1.48;y+=.18)box(-7.37,y,z,.015,.16,.28,'#ada994');box(-6.8,.94,5.1,.7,.025,.8,'#4c5754');box(-6.9,.98,5.5,.05,.32,.05,'#aaa899');box(-6.8,.95,7.8,.85,.03,.9,'#292d29');for(let z of [7.55,8])box(-6.8,.99,z,.34,.01,.23,'#535c52');table(-4.1,7.8,1.8,1.2);for(let x of [-5.25,-2.95]){box(x,.43,7.8,.55,.08,.55,'#4e3e2a',true);box(x,.45,8.07,.55,.62,.06,'#67503a');legs(x,7.8,.5,.5)}windowPane(-7.37,4,'x');box(-2.8,0,3.1,.8,1.9,.85,'#c2bba6',true);box(-2.35,.65,3.1,.04,.07,.07,'#676a59');
