box(-4.1,.48,8.6,.42,.63,.4,'#444a3b');box(-4.1,1.09,8.6,.25,.29,.24,s.memory<70?'#555549':'#aca18a');box(-4.1,1.31,8.6,.29,.1,.26,'#aaa99b');
