box(5.65,.15,7.6,2,.42,3,'#493627',true);box(5.65,.57,7.6,1.95,.18,2.95,'#aba58f');box(5.65,.75,7.25,1.97,.045,2.2,'#58685d');box(5.65,.76,8.65,1.5,.16,.55,'#c5bda5');box(5.65,.1,9.2,2.15,1.1,.12,'#584631');box(7,.0,8.6,.65,.72,.7,'#63503a',true);box(7,.72,8.6,.7,.04,.75,'#927754');box(6.98,.76,8.6,.36,.09,.22,'#292f2a');box(7.06,.86,8.6,.09,.012,.07,'#b2a16e');box(3.1,0,9,1.7,2.35,.8,'#65563e',true);box(3.1,.05,8.57,.025,2.25,.025,'#2c2e25');for(let x of [2.95,3.25])box(x,1.12,8.54,.025,.18,.025,'#b4a07a');table(5.7,3.1,2,.8);windowPane(7.37,4.5,'x');picture(4.5,9.88,'z');
