function canWalk(x,z){let inside=(x>-8.8&&x<8.8&&z> -10.8&&z<0)||(Math.abs(x)<1.38&&z>-.2&&z<12.2)||(x>-7.35&&x<7.35&&z>2.2&&z<9.8)||(Math.abs(x)<3.35&&z>12&&z<17.8);return inside&&!house.solids.some(b=>Math.abs(x-b.x)<b.w/2+.15&&Math.abs(z-b.z)<b.d/2+.15&&(house.jumpHeight||0)<b.y+b.h-.02&&(house.jumpHeight||0)+1.65>b.y)}
function houseRoom(){return house.z<-.2?(house.x< -4&&house.z< -5?'shed':'garden'):house.z>12?'spare':house.x<-1.5?'kitchen':house.x>1.5?'bedroom':'hall'}
function targets(){return [{name:(house.doors.kitchen?'Close':'Open')+' kitchen door',p:[-1.4,1.1,6],fn:()=>toggleDoor('kitchen')},{name:(house.doors.bedroom?'Close':'Open')+' bedroom door',p:[1.4,1.1,6],fn:()=>toggleDoor('bedroom')},{name:(house.doors.spare?'Close':'Open')+' spare room door',p:[0,1.1,12],fn:()=>toggleDoor('spare')},{name:'Childhood photograph',p:[-1.3,1.6,3],fn:()=>inspect('photo')},{name:'Speak to Mother',p:[-4.1,1.3,8.6],fn:()=>{modal('Mother',s.memory>=80?'“Your room is ready, darling. It has always been there.”':s.memory>=40?'“My child is upstairs. You must be the nurse.”':'“Please leave. You’re upsetting my child.”',[['Step away',close]])}},{name:'Kitchen drawer',p:[-6.2,.425,6.3],fn:choice},{name:'Cassette tape',p:[6.9,.9,8.6],fn:()=>inspect('tape')},{name:'Brass key',p:[7,.98,8.6],fn:()=>inspect('key')},{name:'Play / erase recording',p:[6.85,1.2,8.6],fn:()=>s.day===2?choice():modal('Cassette player','The recording is still here. It remembers what you do not.',[['Listen',()=>inspect('tape')],['Leave it',close]])},{name:'Read tomorrow’s diary',p:[0,1.1,16.6],fn:diary},...(s.day===3?[{name:'Face the room',p:[2,1.5,16.8],fn:finale}]:[])]}
function toggleDoor(id){house.doors[id]=!house.doors[id];buildHouse();tone(55,.7);say(house.doors[id]?'The door swings open. The house seems to hold its breath.':'You pull the door closed.')}
house.pointer=null;house.press=null;
function pointerPosition(e){const r=canvas.getBoundingClientRect();return [(e.clientX-r.left)*1000/r.width,(e.clientY-r.top)*690/r.height]}
function locked(){return document.pointerLockElement===canvas}
function surface(t){let x=t.p[0],y=t.p[1],z=t.p[2],w=.35,h=.3,axis='z';if(t.name.includes('door')){w=1.28;h=2.35;y=1.175;let id=t.name.includes('kitchen')?'kitchen':t.name.includes('bedroom')?'bedroom':'spare';if(id==='spare'){if(house.doors[id]){x=.655;z=12.62;axis='x';w=1.3}else{x=0;z=11.925}}else{let sign=id==='kitchen'?-1:1;if(house.doors[id]){x=sign*2.1;z=6.645;axis='z';w=1.3}else{x=sign*1.425;z=6;axis='x'}}}else if(t.name.includes('photograph')){w=.5;h=.65;axis='x';x=-1.345;y=1.625;z=3;}else if(t.name.includes('Mother')){w=.42;h=1.12;y=1.05;}else if(t.name.includes('drawer')){w=.6;h=.61;axis='x';x=-6.2;y=.425;z=6.3;}else if(t.name.includes('diary')){w=.44;h=.33;axis='floor';x=-.1;y=.858;z=16.8;}else if(t.name.includes('key')){w=.09;h=.07;axis='floor';y=.874;x=7.06;}else if(t.name.includes('Cassette')||t.name.includes('recording')){w=.36;h=.22;axis='floor';y=.852;x=6.98;}else{w=.4;h=1.75;y=.875;z=16.84;x=2.1;}
return axis==='x'?[[x,y-h/2,z-w/2],[x,y-h/2,z+w/2],[x,y+h/2,z+w/2],[x,y+h/2,z-w/2]]:axis==='floor'?[[x-w/2,y,z-h/2],[x+w/2,y,z-h/2],[x+w/2,y,z+h/2],[x-w/2,y,z+h/2]]:[[x-w/2,y-h/2,z],[x+w/2,y-h/2,z],[x+w/2,y+h/2,z],[x-w/2,y+h/2,z]];
}

function insidePolygon(p,v){let inside=false;for(let i=0,j=v.length-1;i<v.length;j=i++){let a=v[i],b=v[j];if(((a[1]>p[1])!==(b[1]>p[1]))&&(p[0]<(b[0]-a[0])*(p[1]-a[1])/(b[1]-a[1])+a[0]))inside=!inside}return inside}
function visibleTo(t){let dx=t.p[0]-house.x,dz=t.p[2]-house.z,dist=Math.hypot(dx,dz);for(let d=.1;d<dist-.4;d+=.1){let x=house.x+dx*d/dist,z=house.z+dz*d/dist,y=1.55+(house.jumpHeight||0)+(house.walkBob||0)+(t.p[1]-1.55-(house.jumpHeight||0))*d/dist;if(house.solids.some(b=>y>b.y&&y<b.y+b.h&&Math.abs(x-b.x)<b.w/2&&Math.abs(z-b.z)<b.d/2))return false}return true}
function updateTargets(){house.cachedAngle=house.a;house.cos=Math.cos(house.a);house.sin=Math.sin(house.a);const aim=locked()?[500,345]:(house.pointer||[500,345]);let visible=[];house.target=null;
for(let t of targets()){let distance=Math.hypot(t.p[0]-house.x,t.p[2]-house.z);if(distance>2.4||!visibleTo(t))continue;let world=surface(t),v=clip(world.map(view));if(v.length<3)continue;let points=v.map(screen);if(points.every(p=>p[0]<0)||points.every(p=>p[0]>1000)||points.every(p=>p[1]<0)||points.every(p=>p[1]>690))continue;let center=points.reduce((p,q)=>[p[0]+q[0]/points.length,p[1]+q[1]/points.length],[0,0]);let hit=insidePolygon(aim,points)||Math.hypot(center[0]-aim[0],center[1]-aim[1])<18;visible.push({...t,points,distance,hit})}
visible.sort((a,b)=>a.distance-b.distance);house.target=visible.find(t=>t.hit)||null;for(let t of visible){ctx.strokeStyle=t===house.target?'#ffe3a0':'#bca477';ctx.lineWidth=t===house.target?3:1.4;ctx.fillStyle=t===house.target?'#ffdf8936':'#e5c5820c';ctx.beginPath();t.points.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.closePath();ctx.fill();ctx.stroke()}
const cross=document.getElementById('crosshair'),hint=document.getElementById('interaction-hint');if(cross){cross.style.left=aim[0]/10+'%';cross.style.top=aim[1]/6.9+'%';cross.classList.toggle('ready',!!house.target);let text=house.target?'Click / E to interact':locked()?'Esc releases the mouse':'Click to capture mouse · Esc to release';if(hint.textContent!==text)hint.textContent=text;canvas.style.cursor=locked()?'none':house.target?'pointer':'crosshair'}
}

const originalRender=render;draw=()=>{};render=function(){originalRender();$('spots').replaceChildren();buildHouse();houseDraw();$('nav').replaceChildren();let help=document.createElement('span');help.className='small';help.textContent='WASD WALK · SHIFT SPRINT · SPACE JUMP · MOUSE LOOK · CLICK / E INTERACT · ESC RELEASE';$('nav').append(help);let b=document.createElement('button');b.textContent='HOUSE MAP';b.onclick=showMap;$('nav').append(b);document.querySelector('.scene-caption').textContent='MOVE CLOSER TO INVESTIGATE OBJECTS'};
function showMap(){modal('The house','Kitchen ← Hallway → Bedroom\nAt the end of the hallway: the spare room.\n\nWalk through the doors, or choose a room below to move there.',Object.entries(rooms).map(([id,name])=>[name,()=>{if(id!=='hall')house.doors[id]=true;[house.x,house.z,house.a]=spawn[id];s.room=id;save();close()}]).concat([['Back to the house',close]]))}
const originalStart=start;start=function(){originalStart();[house.x,house.z,house.a]=spawn[s.room]||spawn.hall;if(s.room!=='hall')house.doors[s.room]=true;buildHouse();houseDraw()};
const originalSleep=sleep;sleep=function(){let day=s.day;originalSleep();if(s.day!==day){[house.x,house.z,house.a]=spawn.hall;house.pitch=0;house.doors={kitchen:false,bedroom:false,spare:false};buildHouse()}};$('sleep').onclick=()=>sleep();
const originalReset=reset;reset=function(){[house.x,house.z,house.a]=spawn.hall;house.pitch=0;house.doors={kitchen:false,bedroom:false,spare:false};originalReset()};
function paused(){return !$('overlay').classList.contains('hidden')}
window.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA'].includes(e.target.tagName))return;let k=e.key.toLowerCase();if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright','e','shift',' '].includes(k)){if(!paused())e.preventDefault();house.keys[k]=true;if(k==='e'&&!e.repeat&&!paused()&&house.target)house.target.fn()}});window.addEventListener('keyup',e=>delete house.keys[e.key.toLowerCase()]);window.addEventListener('blur',()=>house.keys={});window.addEventListener('resize',()=>{house.dirty=true});
canvas.style.touchAction='none';
const gameScene=document.querySelector('.scene');function expandFallback(){gameScene.classList.toggle('expanded');if(gameScene.classList.contains('expanded'))gameScene.append($('overlay'));else document.body.append($('overlay'));house.dirty=true}
function captureMouse(){if(paused())return;try{const result=canvas.requestPointerLock?.();if(result?.catch)result.catch(()=>{say('Mouse capture is unavailable here. Drag to look around.');house.dirty=true})}catch{say('Drag to look around; this browser could not capture the mouse.')}}
canvas.addEventListener('pointerdown',e=>{if(paused())return;if(locked()){updateTargets();if(house.target){tone();house.target.fn()}return}house.drag=e.clientX;house.dragY=e.clientY;house.press={x:e.clientX,y:e.clientY,moved:false,touch:e.pointerType==='touch'};canvas.setPointerCapture(e.pointerId)});
canvas.addEventListener('pointermove',e=>{if(locked())return;house.pointer=pointerPosition(e);house.dirty=true;if(house.drag!==null&&!paused()){if(house.press&&Math.hypot(e.clientX-house.press.x,e.clientY-house.press.y)>5)house.press.moved=true;if(house.press?.moved){house.a+=(e.clientX-house.drag)*.006;house.pitch=Math.max(-Math.PI/2,Math.min(Math.PI/2,house.pitch-(e.clientY-house.dragY)*.004))}house.drag=e.clientX;house.dragY=e.clientY}});
canvas.addEventListener('pointerup',e=>{if(!locked()&&house.press&&!paused()){house.pointer=pointerPosition(e);if(!house.press.moved){if(house.press.touch){updateTargets();if(house.target){tone();house.target.fn()}}else captureMouse()}}house.drag=null;house.press=null;house.dirty=true});
canvas.addEventListener('pointercancel',()=>{house.drag=null;house.press=null});canvas.addEventListener('pointerleave',()=>{if(house.drag===null){house.pointer=null;house.dirty=true}});
document.addEventListener('mousemove',e=>{if(locked()&&!paused()){house.a+=e.movementX*.0025;house.pitch=Math.max(-Math.PI/2,Math.min(Math.PI/2,house.pitch-e.movementY*.002));house.dirty=true}});
document.addEventListener('pointerlockerror',()=>{say('Mouse capture is unavailable here. Drag to look around.');house.dirty=true});
document.addEventListener('pointerlockchange',()=>{house.pointer=null;house.keys={};house.drag=null;house.press=null;house.dirty=true});
const oldModal=modal;modal=function(...args){if(locked())document.exitPointerLock();house.keys={};oldModal(...args)};
let crosshair=document.createElement('div');crosshair.id='crosshair';crosshair.setAttribute('aria-hidden','true');let hint=document.createElement('div');hint.id='interaction-hint';hint.setAttribute('aria-live','polite');gameScene.append(crosshair,hint);
let toolbar=document.createElement('div');toolbar.className='game-toolbar';const fullButton=document.createElement('button');fullButton.textContent='⛶ FULLSCREEN';fullButton.onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(gameScene.requestFullscreen)await gameScene.requestFullscreen();else expandFallback();house.dirty=true}catch{expandFallback();house.dirty=true}};toolbar.append(fullButton);for(let [label,fn] of [['MAP',showMap],['END DAY',()=>sleep()]]){let b=document.createElement('button');b.textContent=label;b.onclick=fn;toolbar.append(b)}gameScene.append(toolbar);
document.addEventListener('fullscreenchange',()=>{fullButton.textContent=document.fullscreenElement?'⛶ EXIT FULLSCREEN':'⛶ FULLSCREEN';if(document.fullscreenElement===gameScene)gameScene.append($('overlay'));else document.body.append($('overlay'));house.dirty=true});
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&gameScene.classList.contains('expanded')){gameScene.classList.remove('expanded');document.body.append($('overlay'));house.dirty=true}});

let controls=document.createElement('div');controls.className='walk-controls';[['↶','arrowleft'],['↑','w'],['↓','s'],['↷','arrowright']].forEach(([label,k])=>{let b=document.createElement('button');b.textContent=label;b.setAttribute('aria-label',({arrowleft:'Turn left',w:'Walk forward',s:'Walk backward',arrowright:'Turn right'})[k]);b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);house.keys[k]=true};b.onpointerup=b.onpointercancel=()=>delete house.keys[k];controls.append(b)});document.querySelector('.scene').append(controls);
function houseTick(now){let dt=Math.min(.04,(now-house.last)/1000||0);house.last=now;if(!paused()){let k=house.keys;updateMovement(dt);let prior=[house.x,house.z,house.a];house.a+=((k.arrowright?1:0)-(k.arrowleft?1:0))*dt*1.6;let forward=(k.w||k.arrowup?1:0)-(k.s||k.arrowdown?1:0),side=(k.d?1:0)-(k.a?1:0),scale=forward&&side?.707:1;let nx=house.x+(Math.sin(house.a)*forward+Math.cos(house.a)*side)*dt*(house.sprinting?4.2:2.2)*scale,nz=house.z+(Math.cos(house.a)*forward-Math.sin(house.a)*side)*dt*(house.sprinting?4.2:2.2)*scale;if(canWalk(nx,house.z))house.x=nx;if(canWalk(house.x,nz))house.z=nz;let r=houseRoom();if(r!==s.room){s.room=r;save();render();say(r==='garden'?'An old well and a locked gate wait in the courtyard.':r==='shed'?'A music box waits in the garden shed.':r==='spare'?'The room smells of your childhood. The diary is waiting on the desk.':r==='kitchen'?'Mother is sitting at the kitchen table.':r==='bedroom'?'Your childhood bedroom. Someone has made your bed.':'The hallway feels longer than it should.')}if(house.dirty||house.x!==prior[0]||house.z!==prior[1]||house.a!==prior[2]){houseDraw();house.dirty=false}}requestAnimationFrame(houseTick)}
[house.x,house.z,house.a]=spawn[s.room]||spawn.hall;if(s.room!=='hall')house.doors[s.room]=true;canvas.setAttribute('aria-label','First-person view inside a furnished house. Use WASD to move and arrow keys or dragging to turn.');render();if(!s.ending)modal('Welcome home','The house is now yours to explore.\n\nWASD: walk · Shift: sprint · Space: jump\nClick the game: capture your mouse\nMove mouse: look around · Esc: release\nAim at glowing objects, then click or press E\nFullscreen button: expand the game\nHouse map: move directly to a room\n\nOpen doors and walk inside. Read tomorrow’s diary. Keep two memories. Survive three nights.',[[s.started?'Continue exploring':'Enter the house',()=>start()]]);requestAnimationFrame(houseTick);

// Task HUD follows the same saved story state as the diary and choices.
const taskHUD=document.createElement('section');taskHUD.className='task-hud';taskHUD.setAttribute('aria-label','Current night tasks');taskHUD.setAttribute('aria-live','polite');gameScene.append(taskHUD);
function taskRows(){return s.day===3?[{label:'Read the final diary entry',done:s.read},{label:'Choose the fate of the room',done:!!s.ending}]:[{label:'Read tomorrow’s diary',done:s.read},{label:s.day===1?'Make your choice at the kitchen drawer':'Make your choice at the cassette player',done:s.acted},{label:'End the day',done:false}];}
function updateChecklist(){taskHUD.replaceChildren();let heading=document.createElement('div');heading.className='task-heading';heading.textContent='NIGHT '+s.day+' · TASKS';taskHUD.append(heading);let rows=taskRows(),next=s.ending?-1:rows.findIndex(t=>!t.done);rows.forEach((task,i)=>{let row=document.createElement('div');row.className='task-row'+(task.done?' completed':'')+(i===next?' current':'');let check=document.createElement('span');check.className='task-check';check.textContent=task.done?'✓':'';check.setAttribute('aria-hidden','true');let label=document.createElement('span');label.textContent=task.label;row.setAttribute('aria-label',task.label+(task.done?', completed':i===next?', current task':', pending'));if(i===next)row.setAttribute('aria-current','step');row.append(check,label);taskHUD.append(row)});let note=document.createElement('div');note.className='task-note';note.textContent=s.ending?'Story complete':s.day>1?'✓ '+(s.day-1)+' night'+(s.day>2?'s':'')+' completed':'Complete the highlighted task';taskHUD.append(note)}
const checklistSave=save;save=function(){checklistSave();updateChecklist()};const checklistRender=render;render=function(){checklistRender();updateChecklist()};updateChecklist();
